#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe http-retry-through-a-busy-server. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site few timed
printf '%s\n' 'report ready' > site/report.txt
printf '%s\n' 'up' > site/health.txt
printf '%s\n' 'report ready' > few/report.txt
printf '%s\n' 'report ready' > timed/report.txt
cat > timed.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Fetches a file busy for one request with one retry after one second, and says whether the
# whole command took at least one second and under thirty.
start=$(date +%s)
curl -s --retry 1 --retry-delay 1 -o /dev/null "$1"
end=$(date +%s)
elapsed=$((end - start))
if [ "$elapsed" -ge 1 ] && [ "$elapsed" -lt 30 ]; then echo "waited at least 1 second"; else echo "took $elapsed seconds"; fi
EOF
surl -v --log-file surl.log --directory site --fault "error;scheme=http;reply=503;path=/report.txt;times=2" http://127.0.0.1:8080/ &
sleep 1
curl --no-progress-meter --retry 2 --retry-delay 1 -w "%{http_code} %{num_retries}\n" http://127.0.0.1:8080/report.txt
kill $(jobs -p)
